def leer_cantidad(texto):
    cantidad = int(texto)
    if cantidad <= 0:
        raise ValueError("la cantidad debe ser positiva")
    return cantidad

def subtotal(precio, texto):
    return precio * leer_cantidad(texto)

def subtotal_o_cero(precio, texto):
    try:
        return subtotal(precio, texto)
    except ValueError:
        return 0

subtotal_o_cero(5, "-2")  # 0

